"""Compile actual S3XY full-stalk production functions on the host; no firmware build."""
from pathlib import Path
import tempfile, subprocess
root=Path(__file__).resolve().parents[1]
logic=(root/'vehicle_logic.h').read_text(encoding='utf8')
def block(name):
 a=logic.index(name);start=logic.index('{',a);depth=1;i=start+1
 while depth:
  if logic[i]=='{':depth+=1
  elif logic[i]=='}':depth-=1
  i+=1
 return logic[a:i]
prefix='#include <cassert>\n#include <cstdint>\n#include <cstring>\n#include <initializer_list>\n#include "auto_lane_change_enable_pure.h"\n#include "auto_blinker_pure.h"\nusing esp_err_t=int;\nconstexpr int pdTRUE=1,ESP_OK=0,ESP_ERR_INVALID_STATE=-1,CAN_TX_FRESH_BOTH=3,TURN_SIGNAL_UNSET=0,TURN_SIGNAL_STALK=1,TURN_SIGNAL_STALKLESS=2;\n\nconstexpr uint32_t LEFTSTALK_ID=0x249,BLINKA_S3XY_STOCK_TIMEOUT_MS=1000;\nint canTxBarrierMutex=1,blinkAMux=0,activeTurnSignalVariant=1;bool held=false,passive=false,ready=true,admission=true,canTxAdministrativeHold=false;\nuint32_t now=100;struct{uint32_t epoch=3;}canTxBarrierState;\nbool autoLcS3xyEnabled=true;uint8_t autoLcS3xyActiveDir=0,autoLcS3xyPendingDir=0;uint32_t autoLcS3xyRequestMs=0,autoLcS3xyEpoch=0;\nuint8_t lastReqDir=0;uint32_t autoRequestLastSeenMs=0;volatile uint32_t s3xyBlinkerEventToken=0;\nuint32_t millis(){return now;}uint32_t canTxEpochSnapshot(){return canTxBarrierState.epoch;}\nvoid portENTER_CRITICAL(int*){}void portEXIT_CRITICAL(int*){}\nint xSemaphoreTake(int,int){if(held)return 0;held=true;return 1;}void xSemaphoreGive(int){assert(held);held=false;}\nbool canUsbPassive(){return passive;}bool p4CanAllRunning(){return ready;}uint8_t p4CanBusB(){return 1;}bool twaiNonSummonAdmissionOpen(){return admission;}\ntemplate<class T>bool canTxBarrierAllowsMaskedPure(T,uint32_t e,int){return e==canTxBarrierState.epoch;}\nuint8_t leftStalkChecksum(const uint8_t *p,uint8_t c){return leftStalkChecksumPure(p,c);}\nstruct CanFrame{uint8_t bus=255,can_dlc=0,data[8]={};uint32_t can_id=0;};CanFrame last;int sent=0,sendResult=0,fallback=0;\nint p4CanSendFrame(const CanFrame*f){assert(held);last=*f;sent++;return sendResult;}\nvoid autoBlinkerClearPendingLocked(){}void blinkerTxClearPendingSourceLocked(uint8_t){}void blinkerTxCancelLegacyLocked(){}\nuint32_t blinkerNextEventTokenLocked(volatile uint32_t &v){return ++v;}\nbool requestBlinkerTx(uint8_t,uint8_t,uint32_t,uint32_t){fallback++;return true;}\n'
suffix='int main(){\n uint8_t stock[4]={0,0xa7,0xb0,0x31};stock[0]=leftStalkChecksum(stock,7);\n for(uint8_t dir: {1,1,2,2,1,2,2}){\n  uint8_t expected=autoLcS3xyRawPure(autoLcS3xyActiveDir,dir);\n  assert(requestTurnSignalPulseFromButton(dir));int n=sent;assert(autoLcS3xyConsume(stock,4,0));assert(sent==n+1);\n  assert(last.bus==0&&last.can_id==0x249&&last.can_dlc==4&&(last.data[2]&15)==expected);\n  assert((last.data[2]&0xf0)==0xb0&&(last.data[1]&15)==8&&last.data[3]==0x31);\n  assert(last.data[0]==leftStalkChecksum(last.data,last.data[1]&15));\n }\n assert(requestTurnSignalPulseFromButton(1));assert(!requestTurnSignalPulseFromButton(1));\n now+=1001;int n=sent;assert(autoLcS3xyConsume(stock,4,0));assert(sent==n);\n assert(requestTurnSignalPulseFromButton(1));canTxBarrierState.epoch++;assert(autoLcS3xyConsume(stock,4,0));assert(sent==n);\n assert(requestTurnSignalPulseFromButton(1));passive=true;assert(autoLcS3xyConsume(stock,4,0));assert(sent==n);passive=false;\n assert(requestTurnSignalPulseFromButton(1));sendResult=-1;uint8_t active=autoLcS3xyActiveDir;autoLcS3xyConsume(stock,4,0);assert(autoLcS3xyActiveDir==active);sendResult=0;\n autoLcS3xyEnabled=false;assert(requestTurnSignalPulseFromButton(1)&&fallback==1);\n autoLcS3xyEnabled=true;activeTurnSignalVariant=2;assert(requestTurnSignalPulseFromButton(1)&&fallback==2);\n}\n'
source=prefix+block('static bool autoLcS3xyConsume(')+'\n'+block('static bool requestTurnSignalPulseFromButton(')+'\n'+suffix
with tempfile.TemporaryDirectory() as tmp:
 path=Path(tmp)/'test.cpp';binary=Path(tmp)/'test'
 path.write_text(source,encoding='utf8')
 subprocess.run(['g++','-std=c++17','-Wall','-Wextra','-Werror','-fsanitize=address,undefined','-I',str(root),str(path),'-o',str(binary)],check=True)
 subprocess.run([str(binary)],check=True)
